import React, { useState, useEffect } from 'react';
import { FaMapMarkerAlt, FaChartBar, FaMoneyBillWave, FaCalendarAlt, FaUsers, FaBan } from 'react-icons/fa';
import userService from '../../services/userService';
import advertService from '../../services/advertService';
import styles from './AdminStatisticsPage.module.css';

const AdminStatisticsPage = () => {
    const [statistics, setStatistics] = useState({
        mostPopularAddress: 'Загрузка...',
        mostPopularLevel: 'Загрузка...',
        averageCost: 'Загрузка...',
        adsLastMonth: 0,
        totalUsers: 0,
        blockedUsers: 0
    });
    const [loading, setLoading] = useState(true);

    const levelMap = {
        1: 'D1',
        2: 'D2',
        3: 'D3',
        4: 'D4',
        5: 'D4+',
        'D4Plus': 'D4+'
    };

    useEffect(() => { loadStatistics(); }, []);

    const loadStatistics = async () => {
        try {
            const [advertsRes, usersRes] = await Promise.all([
                advertService.getAllAdverts(),
                userService.getAllUsers()
            ]);
            const adverts = advertsRes.adverts || [];
            const users = usersRes.users || [];

            const now = new Date();
            const lastMonth = new Date(now);
            lastMonth.setMonth(lastMonth.getMonth() - 1);

            const addressCount = {};
            adverts.forEach(a => { addressCount[a.address] = (addressCount[a.address] || 0) + 1; });
            const maxAddress = Math.max(...Object.values(addressCount), 0);
            const mostPopularAddress = Object.keys(addressCount).find(key => addressCount[key] === maxAddress) || 'Нет данных';

            const levelCount = {};
            adverts.forEach(a => {
                const levelName = levelMap[a.gameLevel] || a.gameLevel;
                levelCount[levelName] = (levelCount[levelName] || 0) + 1;
            });
            const maxLevel = Math.max(...Object.values(levelCount), 0);
            const mostPopularLevel = Object.keys(levelCount).find(key => levelCount[key] === maxLevel) || 'Нет данных';

            const avgCost = adverts.length > 0 ? (adverts.reduce((sum, a) => sum + parseFloat(a.cost), 0) / adverts.length).toFixed(2) : '0';
            const adsLastMonth = adverts.filter(a => new Date(a.createdDate) > lastMonth).length;

            setStatistics({
                mostPopularAddress,
                mostPopularLevel,
                averageCost: `${avgCost} руб.`,
                adsLastMonth,
                totalUsers: users.length,
                blockedUsers: users.filter(u => u.isBlocked).length
            });
        } catch (error) {
            console.error('Error loading statistics:', error);
        }
        finally { setLoading(false); }
    };

    const stats = [
        { icon: <FaMapMarkerAlt />, title: 'Самая популярная площадка', value: statistics.mostPopularAddress, color: '#667eea' },
        { icon: <FaChartBar />, title: 'Популярный уровень', value: statistics.mostPopularLevel, color: '#10B981' },
        { icon: <FaMoneyBillWave />, title: 'Средняя стоимость', value: statistics.averageCost, color: '#F59E0B' },
        { icon: <FaCalendarAlt />, title: 'Объявлений за месяц', value: statistics.adsLastMonth, color: '#3B82F6' },
        { icon: <FaUsers />, title: 'Всего пользователей', value: statistics.totalUsers, color: '#8B5CF6' },
        { icon: <FaBan />, title: 'Заблокировано', value: statistics.blockedUsers, color: '#EF4444' }
    ];

    if (loading) return <div className={styles.loading}>Загрузка статистики...</div>;

    return (
        <div className={styles.statisticsPage}>
            <div className={styles.container}>
                <h1 className={styles.title}>Статистика</h1>
                <div className={styles.statsGrid}>
                    {stats.map((stat, index) => (
                        <div key={index} className={styles.statCard}>
                            <div className={styles.statIcon} style={{ background: stat.color }}>{stat.icon}</div>
                            <div className={styles.statContent}>
                                <div className={styles.statTitle}>{stat.title}</div>
                                <div className={styles.statValue}>{stat.value}</div>
                            </div>
                        </div>
                    ))}
                </div>
            </div>
        </div>
    );
};

export default AdminStatisticsPage;
